function checkKey(apiKey) {
  if (!apiKey || apiKey.length === 0) return { error: "missing X-API-Key header" }
  var hash = $security.sha256(apiKey)
  var client = null
  try { client = $app.findFirstRecordByData("mock_clients", "api_key_hash", hash) } catch (err) {}
  if (!client) return { error: "invalid API key" }
  if (!client.getBool("active")) return { error: "client is disabled" }
  return { client: client }
}

function ensureConfig(clientId) {
  var cfg = null
  try { cfg = $app.findFirstRecordByData("mock_config", "client", clientId) } catch (err) {}
  if (!cfg) {
    var col = $app.findCollectionByNameOrId("mock_config")
    cfg = new Record(col)
    cfg.set("client", clientId)
    cfg.set("name", "default"); cfg.set("llm_author_model", "google/gemini-2.5-flash"); cfg.set("author_provider", "gemini"); cfg.set("gemini_model", "gemini-3.5-flash"); cfg.set("dedup_enabled", true); cfg.set("dedup_sets", 5); cfg.set("llm_proofread_model", "qwen/qwen3.5-flash-02-23"); cfg.set("llm_repair_model", "google/gemini-2.5-flash"); cfg.set("image_primary", "z-image"); cfg.set("image_fallback", "p-image-ideogram-1k"); cfg.set("tts_model", "fish-audio/s2.1-pro-free:free"); cfg.set("tts_fallback_model", "microsoft/mai-voice-2-flash"); cfg.set("tts_fallback_voice", "ko-KR-Haena:MAI-Voice-2"); cfg.set("tts_male_voice", ""); cfg.set("tts_female_voice", ""); cfg.set("pdf_parser", "auto"); cfg.set("upscale_pdf_images", true); cfg.set("question_count", 40); cfg.set("reading_count", 20); cfg.set("image_count", 22); cfg.set("image_count_min", 18); cfg.set("image_count_max", 26); cfg.set("difficulty_profile", "creative+difficult"); cfg.set("marks_per_question", 1); cfg.set("max_tokens", 32000); cfg.set("temperature", 0.7); cfg.set("timeout_s", 600); cfg.set("retries", 3); cfg.set("img_retries", 4); cfg.set("push_pb_base", "https://ubt.wts.com.np"); cfg.set("push_pb_email", "shiva@cld.com.np"); cfg.set("push_pb_pass", ""); cfg.set("push_subject_id", "illfosglou0e3j6"); cfg.set("push_exam_type", "mock"); cfg.set("push_exam_status", "draft"); cfg.set("audio_gap_ms", 300); cfg.set("sample_rate", 44100); cfg.set("audio_workers", 4); cfg.set("prompts_json", {}); cfg.set("active", true); 
    $app.save(cfg)
  }
  return cfg
}

